// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public { 
        admin = address(this);
        c = new C(); 
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Ensure only admin can change owner – any caller other than admin should fail
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));

        // The rule: if caller is the admin, the call must succeed and owner becomes newOwner;
        // if caller is not admin, the call must revert.
        if (caller == admin) {
            assertTrue(success);
            assertEq(c.owner(), newOwner);
        } else {
            assertTrue(!success);
            assertEq(c.owner(), admin);
        }
    }
}

